def card(n, topic, grade, good, bad, suggestions, rationale, limit_extra=''):
    title, skill, coverage = TOPICS[topic]
    folder = OUT / f'candidate-{n}'
    folder.mkdir(exist_ok=True)
    if grade == 'Not applicable':
        text = f'## {title} — Not applicable\n\nScope: Candidate {n}. {BASE_SCOPE}\n\nCoverage: {coverage}\n\nRationale: No new security-sensitive actor, authorization policy, secret, dependency, input-to-sink route, or attacker-driven resource decision is implicated in this evolution. Receipt writes are still owned by the supplied local command, and detachment only changes its required post-cancellation completion. This does not claim a general security audit passed.\n\nLimits: {COMMON_LIMIT}\n\nSkill read: ../../review-skills/{skill}/SKILL.md (resolved from the frozen packet); no security decision reference was needed after conditional applicability assessment.\n'
    else:
        counts = {sev: sum(f['severity'] == sev for f in bad) for sev in ['critical', 'major', 'moderate', 'minor']}
        strengths = '\n'.join(f'- [G{i+1}] {g}' for i,g in enumerate(good)) or '- None verified.'
        failures = '\n'.join(f"- [{f['id']}][{f['severity']}][introduced] {f['cause']} {f['evidence']}" for f in bad) or '- None found.'
        changes = '\n'.join(f"- [{f['id']}] {f['correction']} Owner: {f['primary_owner']}." for f in bad) or '- None needed.'
        changes += ('\n\nUngraded related findings: ' + suggestions) if suggestions else ''
        text = f'## {title} — {grade}\n\nScope: Candidate {n}. {BASE_SCOPE}\n\nCoverage: {coverage} All material obligations within this topic boundary were assessed; scope does not expand to absent unrelated infrastructure.\n\nRationale: {rationale}\n\nFinding counts: ' + ', '.join(f'{s}={counts[s]}' for s in counts) + f'\n\nGood\n\n{strengths}\n\nBad\n\n{failures}\n\nSuggested changes\n\n{changes}\n\nLimits: {COMMON_LIMIT} {limit_extra}\n\nChecks: {checks(n)} Exact commands/environment and raw stdout/stderr are stored in ../candidate-{n}-*.json; supplied facts remain separately labeled in ../../provided-checks-{n}.json.\n\nSkill read: ../../review-skills/{skill}/SKILL.md and its decision reference; packet report grading/reporting/orchestration references were also read.\n'
    (folder / f'{topic}.md').write_text(text)

