    card(n, 'deployment', 'A', [f"The supplied flags/validation/signal host is byte-identical to original at {src(n,'cmd/finalize/main.go',17)}; finalization completes before the existing failure exit at {src(n,'cmd/finalize/main.go',53)}.", f"Independently built actual-minimum and host children preserve accepted stdout and the receipt after interruption and return exit 2 for interruption/real receipt-write failure. The relevant command runtime boundary is operated successfully."], [], 'Candidate 1 T1 must be corrected for a usable declared-minimum test gate, but no absent CI workflow is inferred and the runtime receipt/status contract independently passes.' if n == 1 else '', 'All local CLI build/configuration/termination effects implicated by this evolution are assessed. No introduced runtime operation defect found; container, rollout and broader release checks are outside the provided command-only scope, not missing requirements.')

    applicability = []
    for key, (title, skill, reason) in TOPICS.items():
        applicability.append({'id': key, 'topic': title, 'status': 'not_applicable' if key == 'security' else 'complete', 'reason': reason, 'owner': 'context_checked_transfer_review', 'skill': str(ROOT/'review-skills'/skill/'SKILL.md'), 'card': f'{key}.md'})
    findings = [F1, T1, T2, T3] if n == 1 else [C2T1]
    manifest = {'candidate': n, 'mode': 'changeset', 'scope': BASE_SCOPE, 'base': 'original', 'head': f'candidate-{n}', 'source_snapshots': '../source-snapshots.json', 'inspected_paths': SOURCE_PATHS, 'additional_context': ['original/* relevant counterparts', 'provided-contract-probes/contract_test.go', f'provided-checks-{n}.json', 'frozen review-skills and relevant decision references'], 'excluded': ['repository/planning/results/writing skills', 'arm mapping', 'unrelated repository audit', 'mutations beyond supplied single factual sensitivity result'], 'applicability': applicability, 'boundaries': [{'id': b, 'status': 'complete', 'owner': 'context_checked_transfer_review'} for b in ['apply-to-accepted-count','cancellation-classification-and-cause','independent-error-tree-retention','bounded-surviving-finalization-to-Run-return','Run-to-command-status-and-receipt','authored-test-controller-lifetime','minimum-to-nested-build-compiler']], 'checks': checks(n), 'limits': COMMON_LIMIT, 'reviewer_diagnostics': {'status': 'supplementary, not frozen efficacy', 'source': '../diagnostic_contract_test.go'}}
    folder = OUT / f'candidate-{n}'
