    (folder/'findings.json').write_text(json.dumps({'confirmed':findings,'reconciliation':'F1 is counted once across three topics; test corrections are independently required, not duplicates of production error aggregation. No topic-card grades are averaged. No unsupported context-value propagation contract or broad systemic reach is assumed.' if n == 1 else 'One controller ownership cause covers both blocked library and child tests. No immutable production hang is reported. Context values are outside the explicit finalizer contract.','ungraded_concerns':[]},indent=2)+'\n')
